package br.com.ipedtools.mcp.gui;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/** Configuration text generated by the configurator for each client option. */
class ClientConfigTextTest {

    private static final String EXE = "C:\\Program Files\\IPED-Tools-MCP\\IPED-Tools-MCP.exe";
    private static final String JAR = "C:\\build\\iped-tools-mcp-runner.jar";

    private static String option(String startsWith) {
        for (String o : MainWindow.CLIENT_OPTIONS) {
            if (o.startsWith(startsWith)) {
                return o;
            }
        }
        throw new AssertionError("opção não encontrada: " + startsWith);
    }

    @Test
    void testOptionsNameOnlySupportedClients() {
        for (String o : MainWindow.CLIENT_OPTIONS) {
            assertFalse(o.toLowerCase().contains("cursor"), "opção cita cliente sem guia: " + o);
        }
        assertTrue(java.util.List.of(MainWindow.CLIENT_OPTIONS).contains("Claude Desktop / Antigravity (JSON)"));
    }

    @Test
    void testJsonOptionWithExecutable() {
        String text = MainWindow.configText(option("Claude Desktop"), EXE);
        assertTrue(text.contains("\"mcpServers\""));
        assertTrue(text.contains("\"command\": \"C:\\\\Program Files\\\\IPED-Tools-MCP\\\\IPED-Tools-MCP.exe\""),
                "o caminho deve vir com as barras escapadas: " + text);
        assertTrue(text.contains("\"--stdio\""));
    }

    @Test
    void testJsonOptionWithJarPutsJvmOptionsBeforeJar() {
        String text = MainWindow.configText(option("Claude Desktop"), JAR);
        assertTrue(text.contains("\"command\": \"java\""));
        int encoding = text.indexOf("\"-Dfile.encoding=UTF-8\"");
        int jar = text.indexOf("\"-jar\"");
        assertTrue(encoding > 0 && jar > encoding, "as opções da JVM vêm antes de -jar: " + text);
        assertTrue(text.indexOf("\"--stdio\"") > jar);
    }

    @Test
    void testLmStudioFormHasCommandAndStdio() {
        String text = MainWindow.configText(option("LM Studio (Formulário"), EXE);
        assertTrue(text.contains("Comando: " + EXE));
        assertTrue(text.contains("--stdio"));
        assertTrue(text.contains("Copiar prompt"), "o LM Studio não lista prompts: a dica deve indicar o Copiar prompt");
        assertFalse(text.contains("'/start_case'"));
    }

    @Test
    void testLmStudioJsonFile() {
        String text = MainWindow.configText(option("LM Studio (Arquivo"), EXE);
        assertTrue(text.contains("\"servers\"") && text.contains("\"type\": \"stdio\"") && text.contains("\"--stdio\""));
    }
}
